import styled from "styled-components";

export const HeaderContainer = styled.header`
    width: 100%;
    display: flex;
    justify-content: space-between;
    font-family: "Raleway", sans serif;
    
    div{
        width:6rem;
        height:4rem;
        object-fit: contain;
       
    }
    div>img{
        width:100%;
        height: 100%;
        object-fit: contain;
       
    }
    .lets{
       display: flex;
       align-items: center;
        background:#54BC96;
        border-radius:10px;
      
    }

`
